const API_BASE_URL = 'https://localhost:44339/api';

// ============================================
// HELPER FUNCTIONS
// ============================================

function getAuthHeaders(): HeadersInit {
  const token = localStorage.getItem('authToken');
  return {
    'Content-Type': 'application/json',
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
  };
}

async function handleResponse<T>(response: Response): Promise<{ data: T | null; error: any }> {
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({ message: response.statusText }));
    return { data: null, error: errorData };
  }

  const data = await response.json();
  return { data, error: null };
}

// ============================================
// QUERY BUILDER CLASS (Supabase-like API)
// ============================================

class QueryBuilder<T> {
  private endpoint: string;
  private filters: Record<string, any> = {};
  private selectFields: string = '*';
  private limitValue?: number;
  private orderByField?: string;
  private orderDirection: 'asc' | 'desc' = 'asc';
  private singleResult = false;

  constructor(endpoint: string) {
    this.endpoint = endpoint;
  }

  select(fields: string = '*'): this {
    this.selectFields = fields;
    return this;
  }

  eq(field: string, value: any): this {
    this.filters[field] = value;
    return this;
  }

  neq(field: string, value: any): this {
    this.filters[`${field}_ne`] = value;
    return this;
  }

  gt(field: string, value: any): this {
    this.filters[`${field}_gt`] = value;
    return this;
  }

  gte(field: string, value: any): this {
    this.filters[`${field}_gte`] = value;
    return this;
  }

  lt(field: string, value: any): this {
    this.filters[`${field}_lt`] = value;
    return this;
  }

  lte(field: string, value: any): this {
    this.filters[`${field}_lte`] = value;
    return this;
  }

  like(field: string, pattern: string): this {
    this.filters[`${field}_like`] = pattern;
    return this;
  }

  ilike(field: string, pattern: string): this {
    this.filters[`${field}_ilike`] = pattern;
    return this;
  }

  in(field: string, values: any[]): this {
    this.filters[`${field}_in`] = values.join(',');
    return this;
  }

  is(field: string, value: any): this {
    this.filters[field] = value;
    return this;
  }

  order(field: string, options?: { ascending?: boolean }): this {
    this.orderByField = field;
    this.orderDirection = options?.ascending === false ? 'desc' : 'asc';
    return this;
  }

  limit(count: number): this {
    this.limitValue = count;
    return this;
  }

  single(): this {
    this.singleResult = true;
    this.limitValue = 1;
    return this;
  }

  async execute(): Promise<{ data: T | T[] | null; error: any }> {
    try {
      // Build query parameters
      const params = new URLSearchParams();
      
      Object.entries(this.filters).forEach(([key, value]) => {
        params.append(key, String(value));
      });

      if (this.selectFields !== '*') {
        params.append('select', this.selectFields);
      }

      if (this.limitValue) {
        params.append('limit', String(this.limitValue));
      }

      if (this.orderByField) {
        params.append('orderBy', this.orderByField);
        params.append('order', this.orderDirection);
      }

      const url = `${API_BASE_URL}/${this.endpoint}?${params.toString()}`;
      const response = await fetch(url, {
        method: 'GET',
        headers: getAuthHeaders(),
      });

      const result = await handleResponse<T | T[]>(response);

      if (result.error) {
        return result;
      }

      // If single result requested, return first item or null
      if (this.singleResult && Array.isArray(result.data)) {
        return {
          data: result.data.length > 0 ? result.data[0] : null,
          error: null,
        };
      }

      return result;
    } catch (error: any) {
      return { data: null, error: { message: error.message } };
    }
  }

  // Make the query builder thenable so it works with await
  then<TResult1 = { data: T | T[] | null; error: any }, TResult2 = never>(
    onfulfilled?: ((value: { data: T | T[] | null; error: any }) => TResult1 | PromiseLike<TResult1>) | null,
    onrejected?: ((reason: any) => TResult2 | PromiseLike<TResult2>) | null
  ): Promise<TResult1 | TResult2> {
    return this.execute().then(onfulfilled, onrejected);
  }
}

// ============================================
// TABLE METHODS
// ============================================

class SupabaseReplacement {
  from<T = any>(table: string): {
    select: (fields?: string) => QueryBuilder<T>;
    insert: (data: any) => {
      select: (fields?: string) => {
        single: () => Promise<{ data: T | null; error: any }>;
      };
    } & Promise<{ data: T | null; error: any }>;
    update: (data: any) => {
      eq: (field: string, value: any) => Promise<{ data: T | null; error: any }>;
    };
    delete: () => {
      eq: (field: string, value: any) => Promise<{ data: null; error: any }>;
    };
  } {
    return {
      select: (fields: string = '*') => {
        const builder = new QueryBuilder<T>(table);
        return builder.select(fields);
      },

      insert: (data: any) => {
        const insertPromise = (async () => {
          try {
            const response = await fetch(`${API_BASE_URL}/${table}`, {
              method: 'POST',
              headers: getAuthHeaders(),
              body: JSON.stringify(data),
            });

            return await handleResponse<T>(response);
          } catch (error: any) {
            return { data: null, error: { message: error.message } };
          }
        })();

        // Add select method for chaining
        const chainable: any = insertPromise;
        chainable.select = (fields: string = '*') => {
          return {
            single: async () => {
              const result = await insertPromise;
              return result;
            },
          };
        };

        return chainable;
      },

      update: (data: any) => ({
        eq: async (field: string, value: any) => {
          try {
            const response = await fetch(`${API_BASE_URL}/${table}/${value}`, {
              method: 'PUT',
              headers: getAuthHeaders(),
              body: JSON.stringify(data),
            });

            return await handleResponse<T>(response);
          } catch (error: any) {
            return { data: null, error: { message: error.message } };
          }
        },
      }),

      delete: () => ({
        eq: async (field: string, value: any) => {
          try {
            const response = await fetch(`${API_BASE_URL}/${table}/${value}`, {
              method: 'DELETE',
              headers: getAuthHeaders(),
            });

            if (!response.ok) {
              const errorData = await response.json().catch(() => ({ message: response.statusText }));
              return { data: null, error: errorData };
            }

            return { data: null, error: null };
          } catch (error: any) {
            return { data: null, error: { message: error.message } };
          }
        },
      }),
    };
  }

  // Auth methods (stub - main auth is handled by AuthContext)
  auth = {
    getSession: async () => {
      const token = localStorage.getItem('authToken');
      const userStr = localStorage.getItem('user');

      if (token && userStr) {
        try {
          const user = JSON.parse(userStr);
          return {
            data: {
              session: {
                user,
                access_token: token,
              },
            },
            error: null,
          };
        } catch (error) {
          return { data: { session: null }, error };
        }
      }

      return { data: { session: null }, error: null };
    },

    getUser: async () => {
      const token = localStorage.getItem('authToken');
      const userStr = localStorage.getItem('user');

      if (token && userStr) {
        try {
          const user = JSON.parse(userStr);
          return {
            data: { user },
            error: null,
          };
        } catch (error) {
          return { data: { user: null }, error };
        }
      }

      return { data: { user: null }, error: null };
    },

    onAuthStateChange: (callback: (event: string, session: any) => void) => {
      // This is a simplified version - the real auth state is managed by AuthContext
      const checkAuth = () => {
        const token = localStorage.getItem('authToken');
        const userStr = localStorage.getItem('user');

        if (token && userStr) {
          const user = JSON.parse(userStr);
          callback('SIGNED_IN', { user, access_token: token });
        } else {
          callback('SIGNED_OUT', null);
        }
      };

      // Check on mount
      checkAuth();

      // Listen for storage changes (logout in another tab)
      const handleStorageChange = (e: StorageEvent) => {
        if (e.key === 'authToken') {
          checkAuth();
        }
      };

      window.addEventListener('storage', handleStorageChange);

      return {
        data: {
          subscription: {
            unsubscribe: () => {
              window.removeEventListener('storage', handleStorageChange);
            },
          },
        },
      };
    },

    signInWithPassword: async (credentials: { email: string; password: string }) => {
      // This should use AuthContext instead, but keeping for compatibility
      console.warn('Please use AuthContext for authentication');
      return { data: null, error: { message: 'Use AuthContext for authentication' } };
    },

    signOut: async () => {
      // This should use AuthContext instead, but keeping for compatibility
      console.warn('Please use AuthContext for authentication');
      localStorage.removeItem('authToken');
      localStorage.removeItem('user');
      return { error: null };
    },
  };

  // Real-time subscriptions (stub)
  channel(name: string) {
    return {
      on: (event: string, options: any, callback: any) => {
        console.log('Real-time subscriptions not implemented with .NET API');
        return this.channel(name);
      },
      subscribe: () => {
        console.log('Real-time subscriptions not implemented with .NET API');
        return { unsubscribe: () => {} };
      },
    };
  }

  removeChannel(channel: any) {
    // No-op for now
  }

  // Storage methods (for file uploads)
  storage = {
    from: (bucket: string) => ({
      upload: async (path: string, file: File) => {
        try {
          const formData = new FormData();
          formData.append('file', file);
          formData.append('path', path);

          const response = await fetch(`${API_BASE_URL}/storage/${bucket}/upload`, {
            method: 'POST',
            headers: {
              Authorization: `Bearer ${localStorage.getItem('authToken')}`,
            },
            body: formData,
          });

          if (!response.ok) {
            const error = await response.json();
            return { data: null, error };
          }

          const data = await response.json();
          return { data, error: null };
        } catch (error: any) {
          return { data: null, error: { message: error.message } };
        }
      },

      getPublicUrl: (path: string) => {
        return {
          data: {
            publicUrl: `${API_BASE_URL}/storage/${bucket}/${path}`,
          },
        };
      },

      remove: async (paths: string[]) => {
        try {
          const response = await fetch(`${API_BASE_URL}/storage/${bucket}/delete`, {
            method: 'POST',
            headers: getAuthHeaders(),
            body: JSON.stringify({ paths }),
          });

          if (!response.ok) {
            const error = await response.json();
            return { data: null, error };
          }

          return { data: { paths }, error: null };
        } catch (error: any) {
          return { data: null, error: { message: error.message } };
        }
      },
    }),
  };
}

